  "claims": [
    {
      "claim": "In fasted healthy subjects, propranolol—a lipophilic basic amine with a basic pKa near 9.5, similar to the query's ionization profile—has absolute oral bioavailability 27.2%, above the 20% threshold.",
      "card_ids": ["C10", "C25"]
    },
    {
      "claim": "Metoprolol, a lipophilic basic secondary amine bearing a methoxyphenyl group, shows systemic availability 84% in cirrhosis (78 ± 12% excluding portocaval anastomosis), supporting high F for this structural class.",
      "card_ids": ["C01", "C15", "C22", "C30", "C31"]
    },
    {
      "claim": "Diphenhydramine, a lipophilic basic amine, has systemic availability 0.69 after oral dosing in fasted healthy volunteers.",
      "card_ids": ["C13", "C33"]
    },
    {
      "claim": "Verapamil, a lipophilic basic amine with a dimethoxyphenyl group, has absolute F 52.3% in cirrhosis; the lowest visible verapamil record is 22%, still above 20%.",
      "card_ids": ["C05", "C06", "C19", "C43", "C35"]
    },
    {
      "claim": "L3 human oral exposure records for structurally related basic amines (cinacalcet, tamsulosin) show measurable oral Cmax and AUC, supporting oral absorption; they lack IV comparators and do not directly quantify F.",
      "card_ids": ["C44", "C48", "C52", "C55", "C50"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C44", "C48", "C52", "C55", "C50"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "L3 records are oral AUC/Cmax without IV comparators, so they cannot quantify absolute F.",
    "Most high-F records come from cirrhosis or modified-release conditions; fasted healthy analogs are limited to propranolol and diphenhydramine.",
    "The query's very low neutral fraction (0.01) at pH 7.4 could reduce passive permeability, but no direct permeability or in vivo data are available; propranolol with a similar basic pKa still achieves F 27.2%.",
    "C35 reports 22% for verapamil, lower than other verapamil cirrhosis records (52%), but still above 20%; the source of this discrepancy is not resolved."
  ],
  "decision_summary": "Predicted high because all visible records report F values ≥22% for structurally similar lipophilic basic amines (propranolol 27.2% fasted, metoprolol 84% cirrhosis, diphenhydramine 69% fasted, verapamil 22–52%), and L3 human oral exposure records for related basic amines (cinacalcet, tamsulosin) show measurable oral Cmax/AUC; no affirmative evidence supports F < 20%. Confidence is moderate because transfer is indirect and no direct query F is available."
}

